def page(title,desc,body,nav=''):
 return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="strict-origin-when-cross-origin"><meta name="theme-color" content="#0a0c0d"><meta name="description" content="{escape(desc,quote=True)}"><title>{escape(title)} | Christopher Dean Books</title><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600;700&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/style.css"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:image" content="https://chrisdeanbooks.com/assets/img/wildborn-promo.webp"><meta property="og:type" content="website"></head><body data-current="{nav}">{NAV}<main>{body}</main>{FOOTER}{CART}<script src="/assets/catalog.js"></script><script src="/assets/app.js" defer></script></body></html>'''
HERO='''<section class="hero" id="home"><div class="hero-ambient"></div><div class="hero-grain"></div><div class="hero-inner"><div class="hero-copy"><div class="hero-kicker"><span class="live-dot"></span> INDEPENDENT FANTASY FICTION <span class="kicker-rule"></span> EST. 2026</div><p class="hero-above">A STORY FROM THE WILD</p><h1>The world is<br><i>waiting</i> to be<br>discovered.</h1><p class="hero-description">Enter extraordinary worlds of myth, survival and impossible choices. Discover the stories of Christopher Dean — where every journey leaves its mark.</p><div class="hero-buttons"><a class="btn btn-gold" href="/books/wildborn/">Explore Wildborn <span>↗</span></a><a class="btn btn-outline" href="#books">Browse all books <span>↓</span></a></div><div class="hero-stats"><div><b>01</b><span>FEATURED RELEASE</span></div><span class="stat-sep"></span><div><b>2026</b><span>A NEW CHAPTER</span></div><span class="stat-sep"></span><div><b>AU</b><span>INDEPENDENT AUTHOR</span></div></div></div><div class="hero-art"><div class="art-glow"></div><div class="art-disc"></div><img src="/assets/img/wildborn-cover.webp" alt="Wildborn book cover artwork" fetchpriority="high"><span class="art-vertical">THE WILDERNESS IS CALLING</span><div class="hero-caption"><span>01 / FEATURED BOOK</span><strong>WILDBORN</strong></div></div></div><div class="hero-bottom"><span>SCROLL TO EXPLORE</span><span class="scroll-line"></span><span>FANTASY · ADVENTURE · THE UNEXPECTED</span></div></section>'''
BOOKS='''<section class="section books-section" id="books"><div class="section-top"><div><p class="eyebrow"><span class="small-diamond">✦</span> THE LIBRARY</p><h2>Stories to <em>lose yourself in.</em></h2></div><p class="section-description">From moonlit forests to worlds reduced to ruin, there is always another story waiting to be told.</p></div><div class="shelf-tabs" role="group" aria-label="Filter books"><button class="shelf-tab active" data-filter="all">All stories</button><button class="shelf-tab" data-filter="available">Available now</button><button class="shelf-tab" data-filter="upcoming">Coming soon</button></div><div class="book-rail"><article class="book-tile" data-status="available"><a class="tile-art" href="/books/wildborn/"><img src="/assets/img/wildborn-cover.webp" alt="Wildborn cover" loading="eager"><span class="tile-badge available-badge">AVAILABLE NOW</span><span class="tile-overlay">EXPLORE THE BOOK <span>↗</span></span></a><div class="tile-meta"><div><span class="tile-type">FANTASY · ADVENTURE</span><a href="/books/wildborn/"><h3>Wildborn</h3></a><p>A tale of survival, belonging and finding your own strength.</p></div><button class="tile-arrow" onclick="location.href='/books/wildborn/'" aria-label="View Wildborn">↗</button></div></article><article class="book-tile" data-status="upcoming"><a class="tile-art" href="/books/his-name-was-monster/"><img src="/assets/img/monster-cover.webp" alt="His Name Was Monster concept cover" loading="eager"><span class="tile-badge soon-badge">COMING SOON</span><span class="tile-overlay">DISCOVER THE WORLD <span>↗</span></span></a><div class="tile-meta"><div><span class="tile-type">DARK FANTASY · EPIC</span><a href="/books/his-name-was-monster/"><h3>His Name Was Monster</h3></a><p>One broken world. A creature with unfinished business.</p></div><button class="tile-arrow" onclick="location.href='/books/his-name-was-monster/'" aria-label="View His Name Was Monster">↗</button></div></article><article class="coming-tile" data-status="upcoming"><div class="coming-art"><div class="coming-orbit">✧</div><span>CHAPTERS YET<br>UNWRITTEN</span><i>More worlds are on the horizon.</i></div><div class="tile-meta"><div><span class="tile-type">ON THE HORIZON</span><h3>The stories ahead</h3><p>New adventures are taking shape.</p></div></div></article></div></section>'''
FEATURE='''<section class="feature"><div class="feature-image"><img src="/assets/img/wildborn-promo.webp" loading="eager" alt="Wildborn official release promotional artwork"></div><div class="feature-copy"><p class="eyebrow"><span class="small-diamond">✦</span> THE FEATURED RELEASE</p><h2>Born of the <i>wilderness.</i><br>Forged by fate.</h2><p>In <strong>Wildborn</strong>, survival is only the beginning. Enter a world of fierce loyalties, difficult choices, and a bond to the wild that cannot be broken.</p><div class="feature-details"><span>FANTASY / ADVENTURE</span><span>AVAILABLE IN PRINT & DIGITAL</span></div><a class="text-link" href="/books/wildborn/">Discover the story <span>↗</span></a></div></section>'''
ABOUT='''<section class="about-preview" id="author"><div class="about-mark"><div class="ornament">✧</div><img src="/assets/img/christopher-dean-logo.webp" alt="Christopher Dean author logo" loading="eager"><span>THE PERSON BEHIND THE PAGES</span></div><div class="about-copy"><p class="eyebrow">MEET THE AUTHOR</p><h2>Christopher <em>Dean.</em></h2><p>From the Hunter Valley in New South Wales, Australia, Christopher writes fantasy and speculative fiction driven by immersive worlds, hard-won loyalties and characters who refuse to yield.</p><p>When he isn't writing, you'll find him spending time with family, playing chess, woodworking or competing in Strongman and Highland Games.</p><a class="btn btn-outline" href="/about/">More about Christopher <span>↗</span></a></div></section><section class="bottom-cta"><p class="eyebrow">THE NEXT CHAPTER STARTS HERE</p><h2>Find a story worth <em>staying up for.</em></h2><p>Explore the collection and choose the edition that belongs on your shelf.</p><a class="btn btn-gold" href="/shop/">Visit the bookshop <span>↗</span></a></section>'''
