def inner_hero(kicker,title,subtitle,kind=''):
 return f'<section class="inner-hero {kind}"><div class="inner-hero-inner"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p>{subtitle}</p></div></section>'
WILDBORN='''<section class="book-detail" id="wildborn"><div class="detail-cover-wrap"><div class="detail-glow"></div><img class="detail-cover" src="/assets/img/wildborn-cover.webp" alt="Wildborn book cover"></div><div class="detail-content"><div class="eyebrow"><span class="small-diamond">✦</span> AVAILABLE NOW · FANTASY / ADVENTURE</div><h1>Wildborn</h1><p class="byline">A novel by Christopher Dean</p><div class="detail-rule"></div><h2>To find where you belong, you may have to leave everything you know.</h2><p>Raised among the wild, Anya has learned to survive by trusting her instincts. But the world beyond the forest holds challenges that neither strength nor skill alone can overcome.</p><p>A fantasy adventure about identity, loyalty and the family we find along the way.</p><p class="copy-note">Preview synopsis — replace with your official retail blurb before launch.</p><div class="edition-picker"><h3>Choose your edition</h3><div class="edition-options"><button class="edition selected" data-edition="wildborn-paperback"><span>Paperback<small>Physical copy · shipped from Australia</small></span><strong>A$25.00*</strong></button><button class="edition" data-edition="wildborn-ebook"><span>Ebook<small>Digital edition · private download</small></span><strong>A$8.99*</strong></button></div><button class="btn btn-gold btn-full detail-add" data-add-selected="wildborn">Add to book bag <span>＋</span></button><p class="price-footnote preview-only">* Preview prices only. Orders cannot be placed until checkout is configured.</p></div></div></section><section class="detail-extra"><div class="extra-heading"><p class="eyebrow">INSIDE THE STORY</p><h2>The wilderness <em>doesn't forget.</em></h2></div><div class="extra-grid"><div><span>01 / THE WORLD</span><h3>A world beyond the trees</h3><p>The wild has its own laws. Beyond it lie kingdoms, long memories, and dangers that cannot be outrun.</p></div><div><span>02 / THE HEART</span><h3>Strength and belonging</h3><p>Every journey asks something of us. Some ask us to become more than we thought we could be.</p></div><div><span>03 / THE FORMAT</span><h3>Choose your journey</h3><p>Read in paperback or ebook. Physical copies are packed and posted directly by the author.</p></div></div></section>'''
(p/'books/wildborn/index.html').write_text(page('Wildborn — Book & Editions','Explore Wildborn, an adventurous fantasy novel by Christopher Dean. Preview available paperback and ebook editions.',WILDBORN,'books'))
MONSTER='''<section class="book-detail monster-detail"><div class="detail-cover-wrap"><div class="detail-glow"></div><img class="detail-cover" src="/assets/img/monster-cover.webp" alt="His Name Was Monster cover artwork"></div><div class="detail-content"><div class="eyebrow"><span class="small-diamond">✦</span> COMING SOON · EPIC DARK FANTASY</div><h1>His Name<br>Was Monster</h1><p class="byline">A forthcoming novel by Christopher Dean</p><div class="detail-rule"></div><h2>Some legends are remembered. Others refuse to die.</h2><p>In a world shattered by forces greater than men, a being known only as Monster walks among the ruins. Ancient powers stir, promises bind the living to the dead, and the truth of a broken world waits in the shadows.</p><p>What begins as a journey through destruction may become a reckoning with the beings who allowed it.</p><p class="copy-note">Preview description and concept artwork. Publication details to be confirmed.</p><div class="coming-notice"><span>✦</span><div><strong>Not yet available to order</strong><p>Paperback and ebook editions can be activated when publication details are final.</p></div></div><a class="btn btn-outline" href="/#books">Explore more stories <span>↗</span></a></div></section><section class="quote-panel"><span>THE WORLD IS NOT FINISHED WITH HIM.</span><p>More from this world will be revealed as the story approaches publication.</p></section>'''
(p/'books/his-name-was-monster/index.html').write_text(page('His Name Was Monster — Coming Soon','Discover His Name Was Monster, a forthcoming epic dark fantasy novel by Christopher Dean.',MONSTER,'books'))
SHOP=inner_hero('✦ THE OFFICIAL BOOKSHOP','A book for <em>every journey.</em>','Explore current editions, support an independent author, and have your books sent directly to you.','shop-hero')+'''<section class="shop-content"><div class="shop-top"><div><h2>Available editions</h2><p>Physical books ship directly from the author in Australia. Ebooks will be delivered securely after purchase.</p></div><div class="shop-note">✦ DIRECT FROM THE AUTHOR</div></div><div class="shop-grid"><article class="shop-card"><a href="/books/wildborn/"><img src="/assets/img/wildborn-cover.webp" alt="Wildborn paperback book"></a><div><span class="eyebrow">PHYSICAL EDITION</span><h3>Wildborn · Paperback</h3><p>A beautifully tangible way to enter the wild.</p><span class="shop-price"><span data-price-sku="wildborn-paperback">A$25.00</span> <small class="preview-only">* preview</small></span><button class="btn btn-gold btn-full" data-add="wildborn-paperback">Add paperback <span>＋</span></button></div></article><article class="shop-card"><a href="/books/wildborn/"><img src="/assets/img/wildborn-cover.webp" alt="Wildborn ebook cover"></a><div><span class="eyebrow">DIGITAL EDITION</span><h3>Wildborn · Ebook</h3><p>The story, wherever the road takes you.</p><span class="shop-price"><span data-price-sku="wildborn-ebook">A$8.99</span> <small class="preview-only">* preview</small></span><button class="btn btn-gold btn-full" data-add="wildborn-ebook">Add ebook <span>＋</span></button></div></article></div><p class="shop-disclaimer preview-only">* Prices are examples pending your final approval and Stripe setup. Checkout is disabled in this preview.</p><div class="shop-info"><div><span class="info-symbol">▣</span><h3>Packed with care</h3><p>Paperbacks are fulfilled by Christopher and posted directly to readers.</p></div><div><span class="info-symbol">⌁</span><h3>Secure payments</h3><p>At launch, payments will be processed through Stripe's hosted checkout.</p></div><div><span class="info-symbol">↓</span><h3>Digital access</h3><p>Ebook buyers receive a download after payment. Files are stored privately.</p></div></div></section>'''
(p/'shop/index.html').write_text(page('Official Bookshop','Shop Wildborn paperback and ebook editions directly from Christopher Dean. Australian author direct sales.',SHOP,'shop'))
ABOUTPAGE=inner_hero('✦ THE STORYTELLER','Meet the <em>author.</em>','A little about the person behind the worlds, the characters, and the pages.','about-hero')+'''<section class="about-page"><div class="about-page-art"><div class="about-logo-ring"><img src="/assets/img/christopher-dean-logo.webp" alt="Gold Christopher Dean logo"></div><p>HUNTER VALLEY · NEW SOUTH WALES</p></div><div class="about-page-copy"><span class="eyebrow">CHRISTOPHER DEAN</span><h2>Stories are how we<br><em>live a thousand lives.</em></h2><p>Christopher Dean is an independent Australian author writing fantasy and speculative fiction. He lives in the Hunter Valley of New South Wales with his family, where imagined worlds have a habit of spilling into everyday life.</p><p>His love for fantasy began early, with stories that made the impossible feel within reach. That fascination grew into a passion for creating worlds of his own — places shaped by ancient histories, fierce loyalties and characters confronted by choices with no easy answers.</p><p>Outside his writing, Christopher spends time with his family, plays chess, dabbles in woodworking, and competes in Strongman and Highland Games events. Those interests often make their way into his work: the physical weight of a fight, the strategy behind a conflict, and the bonds that hold people together.</p><p>His work includes <em>Wildborn</em>, with more worlds currently in the making.</p><a class="btn btn-outline" href="/contact/">Get in touch <span>↗</span></a></div></section><div class="about-banner"><span>“There is always another world beyond the page.”</span></div>'''
(p/'about/index.html').write_text(page('About Christopher Dean','Learn about Christopher Dean, Australian fantasy author from the Hunter Valley, New South Wales.',ABOUTPAGE,'about'))
CONTACT=inner_hero('✦ LET’S CONNECT','A story starts with <em>a hello.</em>','For author events, bookstore enquiries, reader messages and collaborations.','contact-hero')+'''<section class="contact-content"><div><p class="eyebrow">SAY HELLO</p><h2>Have something<br><em>on your mind?</em></h2><p>Whether you’re a reader, bookseller, event organiser or fellow storyteller, feel free to reach out. The contact form below will be available when the site’s sending address is connected.</p><div class="contact-small"><span>BASED IN</span><strong>Hunter Valley, NSW, Australia</strong></div></div><form class="contact-form" id="contact-form"><label for="contact-name">Your name</label><input type="text" id="contact-name" name="name" placeholder="Name" minlength="2" maxlength="120" required><label for="contact-email">Email address</label><input type="email" id="contact-email" name="email" placeholder="you@example.com" maxlength="180" required><label for="contact-message">Your message</label><textarea id="contact-message" name="message" placeholder="Your message..." minlength="10" maxlength="4000" rows="6" required></textarea><div class="turnstile-wrap" id="turnstile-wrap"></div><input type="text" name="website" class="honeypot" tabindex="-1" autocomplete="off" aria-hidden="true"><button class="btn btn-gold btn-full" type="submit" disabled>Send message <span>↗</span></button><p class="form-status" role="status">Contact form is disabled until an email address and anti-spam verification are configured.</p></form></section>'''
(p/'contact/index.html').write_text(page('Contact Christopher Dean','Contact Australian fantasy author Christopher Dean for events, reader messages and enquiries.',CONTACT,'contact'))
SUCCESS=inner_hero('✦ ORDER STATUS','Thank you for <em>your order.</em>','Your payment status and any available ebook downloads appear below.','status-hero')+'''<section class="status-content"><div class="status-box" id="order-status"><span class="spinner"></span><p>Checking your payment with our secure checkout provider…</p></div><p class="status-small">Keep your order link safe. Your downloadable files will be available here once payment is confirmed.</p><a href="/" class="text-link">Return to the library ↗</a></section>'''
(p/'success/index.html').write_text(page('Order confirmation','Review your order and collect purchased digital books.',SUCCESS,'shop'))
CANCEL=inner_hero('✦ CHECKOUT','Your story can <em>wait.</em>','Your checkout was cancelled and no order was completed.','status-hero')+'''<section class="status-content"><p>Your book bag is still here whenever you’re ready.</p><button class="btn btn-gold" data-open-cart>Return to your bag <span>↗</span></button><a class="text-link" href="/shop/">Keep browsing ↗</a></section>'''
(p/'cancel/index.html').write_text(page('Checkout cancelled','Return to the shop to continue browsing.',CANCEL,'shop'))
POLICY=inner_hero('✦ THE SMALL PRINT','Shipping & <em>information.</em>','Useful information about orders, deliveries and digital products.','status-hero')+'''<section class="policy-content"><div class="policy-warning">DRAFT — THIS PAGE REQUIRES YOUR CONFIRMED BUSINESS POLICIES BEFORE CHECKOUT GOES LIVE.</div><h2>Shipping</h2><p>Physical books will initially ship to Australian addresses and will be packed and posted by the author. Exact shipping charges, dispatch times, tracking options and carriers will be confirmed and displayed before checkout launches.</p><h2>Digital editions</h2><p>Ebooks will be made available by private download once payment is complete. Supported formats, download limits and customer support details will be confirmed before digital orders are enabled.</p><h2>Returns and refunds</h2><p>Your rights under Australian Consumer Law will be honoured. A complete change-of-mind and damaged-item policy, together with the return contact details, must be finalised before accepting payments.</p><h2>Privacy</h2><p>Stripe will process payment details. To fulfil orders, customer contact and delivery information may be used by Stripe, Cloudflare and the transactional email provider configured for this store. A complete privacy notice, including retention, access and contact details, must be published before launch.</p><h2>Customer enquiries</h2><p>A verified contact email address will be provided before sales are enabled.</p></section>'''
(p/'policies/index.html').write_text(page('Shipping and Policies','Shipping, digital delivery, returns and privacy information for Christopher Dean Books.',POLICY,''))
(p/'404.html').write_text(page('Page not found','This page could not be found.',inner_hero('✦ LOST IN THE PAGES','This chapter <em>is missing.</em>','The page you are looking for could not be found.','status-hero')+'<section class="status-content"><a href="/" class="btn btn-gold">Return home ↗</a></section>',''))
(p/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /success/\nDisallow: /api/\nSitemap: https://chrisdeanbooks.com/sitemap.xml\n')
