(p/'assets/favicon.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#0a0c0d"/><path d="M32 8 37 26 56 32 37 38 32 56 27 38 8 32 27 26Z" fill="#cbaa71"/><circle cx="32" cy="32" r="5" fill="#101215"/></svg>''')
